// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testFuzz_property(address owner, uint256 totalDistributed) public {
        vm.assume(owner != address(0));
        vm.assume(totalDistributed <= 500000000 ether);
        c.XBornID();
        assertEq(c.balanceOf(address(this)), c.totalDistributed());
    }
}
